// 原信件实际受领/实交/返报，分别证明当场两人的旧地点；不把信中人自动当在场者。
#define HANMO_MESSAGE_HANDOFF_TEST_LIBRARY
#include "task_message_handoff_test.cpp"
#include "resident/domains/interaction/known_contacts/known_contact_location.hpp"
int main(){try{
    Fixture f;f.tasks.message_handoffs->version=2;MessageContactHistory history{f.tasks,f.catalog,*f.tasks.message_handoffs};KnownContactLocationAccess read{f.common,*f.shared,nullptr,&history};
    f.finish(f.start("accept_offer"));auto unarrived=read_known_contact_location(read,"sender","recipient");require(unarrived.ok&&!unarrived.value,"acceptance and original addressee do not prove a distant personal meeting");
    f.finish(f.start("deliver_message"));const auto handoff=f.tasks.message_handoffs->receipts.order().front();auto carrier=read_known_contact_location(read,"player","recipient"),recipient=read_known_contact_location(read,"recipient","player");require(carrier.ok&&recipient.ok&&carrier.value&&recipient.value&&carrier.value->source_fact_id==handoff&&recipient.value->observed_tick==12,"actual carrier and recipient know each other at real delivery location");require(read_known_contact_locations(read,"sender").value.rows.empty()&&read_known_contact_locations(read,"stranger").value.rows.empty(),"issuer and unrelated bystander do not receive remote contact knowledge");
    f.shared->places.insert("far_place",{"far_place","other_town",{}});f.common.state().actors.find("recipient")->location=SettlementLocation{"other_town","far_place"};f.finish(f.start("report_offer"));const auto report=f.tasks.message_handoffs->reports.order().front();auto listener=read_known_contact_location(read,"sender","player");require(listener.ok&&listener.value&&listener.value->source_fact_id==report&&listener.value->observed_tick==13,"actual reporter and listener know the returned carrier at reporting time");auto remote=read_known_contact_location(read,"sender","recipient");require(remote.ok&&!remote.value,"report does not turn old letter addressee into an eyewitness encounter");recipient=read_known_contact_location(read,"recipient","player");require(recipient.ok&&recipient.value&&recipient.value->source_fact_id==handoff&&recipient.value->observed_tick==12,"recipient cannot see later reporting location or time");auto finite=read_known_contact_locations(read,"player",0,1);require(finite.ok&&finite.value.rows.size()==1&&finite.value.rows.front().source_fact_id==report&&finite.value.next_cursor==1,"finite list orders original common sources newest first");auto next=read_known_contact_locations(read,"player",1,1);require(next.ok&&next.value.rows.size()==1&&next.value.rows.front().source_fact_id==handoff&&!next.value.next_cursor,"second page keeps exact older actual contact");
    const auto original=encode_common_state(f.common.state());auto stale=read_known_contact_location(read,"player","recipient");require(stale.ok&&stale.value&&stale.value->place_id=="market"&&stale.value->observed_tick==12&&compare_boundary(original,encode_common_state(f.common.state())).exact(),"new current remote coordinate never refreshes old contact source or writes world");
    std::cout<<"KNOWN_MESSAGE_CONTACT: real handoff/report two-person scope; World unrun\n";return 0;
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
